<style>
.gd-page{background:#F8F8F8;color:#142B49;padding:46px 0 72px;min-height:55vh}.gd-wrap{max-width:1200px;margin:auto;padding:0 32px}.gd-eyebrow{color:#2563EB;font-size:11px;font-weight:750;letter-spacing:.17em;text-transform:uppercase}.gd-intro{display:flex;gap:40px;align-items:end;justify-content:space-between;padding-bottom:32px;border-bottom:1px solid #DFE5ED}.gd-intro h1{font-size:clamp(34px,4.2vw,56px);font-weight:750;line-height:1.14;letter-spacing:-.045em;margin-top:14px}.gd-intro h1 span{color:#6F8198}.gd-intro>p{max-width:340px;line-height:1.85;color:#6E7E92;font-size:14px;padding-bottom:5px}.gd-filters{display:flex;gap:20px;justify-content:space-between;align-items:center;padding:25px 0}.gd-categories{display:flex;gap:8px;flex-wrap:wrap}.gd-pill{padding:9px 15px;border:1px solid #DCE3EC;border-radius:24px;font-size:12px;font-weight:600;background:white;white-space:nowrap}.gd-pill[aria-pressed=true]{background:#142B49;color:white;border-color:#142B49}.gd-search{display:flex;gap:8px;flex-shrink:0}.gd-search input{width:220px;min-width:0;border:1px solid #DCE3EC;border-radius:9px;padding:11px 13px;font-size:13px;background:white}.gd-button{display:inline-flex;align-items:center;justify-content:center;gap:9px;padding:11px 17px;min-height:42px;background:#2563EB;color:white;border:1px solid #2563EB;border-radius:9px;font-size:12px;font-weight:650}.gd-button--quiet{color:#142B49;background:white;border-color:#DCE3EC}.gd-featured{display:grid;grid-template-columns:1.25fr 1fr;background:white;border:1px solid #E2E7EE;border-radius:18px;overflow:hidden;margin:0 0 40px}.gd-featured .gd-media{aspect-ratio:1.4;height:100%;min-height:320px;border-radius:0}.gd-featured-content{padding:36px;display:flex;align-items:start;flex-direction:column;justify-content:center}.gd-featured h2{font-size:clamp(24px,2.8vw,34px);line-height:1.35;font-weight:750;letter-spacing:-.025em;margin:16px 0}.gd-featured p{color:#738298;font-size:14px;line-height:1.85;margin-bottom:24px}.gd-section