o 30px;text-align:center}.gd-article-head h1{font-size:clamp(28px,3.7vw,48px);font-weight:750;line-height:1.25;letter-spacing:-.035em;margin:16px 0 22px;overflow-wrap:anywhere}.gd-article-head .gd-meta{justify-content:center}.gd-deck{color:#718197;font-size:16px;line-height:1.9;margin:20px auto 0;max-width:720px}.gd-cover{width:100%;max-height:540px;object-fit:cover;border-radius:16px;margin:0 0 34px}.gd-cover-placeholder{height:200px;margin-bottom:34px}.gd-article-body{max-width:760px;margin:auto;font-size:16px;line-height:1.95;color:#3D5069;overflow-wrap:anywhere}.gd-article-body :is(p,ul,ol,blockquote,pre,table){margin:20px 0}.gd-article-body h2{color:#142B49;font-size:27px;line-height:1.5;font-weight:750;margin:36px 0 16px}.gd-article-body :is(h3,h4){color:#142B49;font-size:21px;font-weight:700;margin:30px 0 14px}.gd-article-body ul{list-style:disc;padding-left:24px}.gd-article-body ol{list-style:decimal;padding-left:24px}.gd-article-body li{margin:10px 0}.gd-article-body a{color:#2563EB;text-decoration:underline}.gd-article-body blockquote{border-left:3px solid #2563EB;padding:12px 22px;background:#EFF4FB}.gd-article-body table{display:block;max-width:100%;overflow:auto;border-collapse:collapse;font-size:13px}.gd-article-body :is(td,th){padding:12px;border:1px solid #DCE3EC;min-width:110px}.gd-article-body pre{overflow:auto;padding:18px;background:#EAF0F7}.gd-related{border-top:1px solid #DFE5ED;margin-top:52px;padding-top:32px}.gd-hotel{background:white;padding:20px;border:1px solid #E3E8EF;border-radius:12px}.gd-hotel h3{margin:12px 0 8px}.gd-page [hidden]{display:none!important}.gd-page :is(a,button,input):focus-visible{outline:2px solid #2563EB;outline-offset:4px}.gd-card a:hover,.gd-read:hover{color:#2563EB}
